-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"edcef0f9-0aa9-5898-9e0c-dae509612b17","inventory_key":"museum-nl:museum-gouda","name":"Museum Gouda","city":"Gouda","province":"Zuid-Holland","street_address":"Oosthaven 9","postal_code":"2801 JX","country":"NL","website_url":"https://www.museumgouda.nl/","latitude":52.010027,"longitude":4.711067,"summary":"Van indrukwekkende altaarstukken tot kleurig Gouds plateel: Museum Gouda laat zien hoeveel kunst de stad heeft voortgebracht en verzameld. Schilderkunst en keramiek vormen een rijke ontmoeting in het historische gasthuis.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude kunst","keramiek","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Museum_Gouda%2C_Gouda_750_jaar.jpg/1280px-Museum_Gouda%2C_Gouda_750_jaar.jpg","caption":"Museum Gouda — Museum Gouda, Gouda 750 jaar","credit":"Agaath","source_url":"https://commons.wikimedia.org/wiki/File:Museum_Gouda,_Gouda_750_jaar.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"b0bd5e77-f9a9-524a-bdc1-245142a24ff9","inventory_key":"museum-nl:fries-museum","name":"Fries Museum","city":"Leeuwarden","province":"Friesland","street_address":"Wilhelminaplein 92","postal_code":"8911 BS","country":"NL","website_url":"https://www.friesmuseum.nl/","latitude":53.199569,"longitude":5.79425,"summary":"Kunst en Friesland kijken elkaar aan in het Fries Museum. Hedendaagse werken, mode en historische voorwerpen bieden uiteenlopende perspectieven op identiteit en landschap. Wisselende tentoonstellingen geven de verzameling steeds een nieuwe context.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","toegepaste kunst","mode"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Het_Fries_Museum_%28Leeuwarden%29_tijdens_de_vrijdag_warenmarkt.jpg/1280px-Het_Fries_Museum_%28Leeuwarden%29_tijdens_de_vrijdag_warenmarkt.jpg","caption":"Fries Museum — Het Fries Museum (Leeuwarden) tijdens de vrijdag warenmarkt","credit":"PerpetualTraveler","source_url":"https://commons.wikimedia.org/wiki/File:Het_Fries_Museum_(Leeuwarden)_tijdens_de_vrijdag_warenmarkt.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"937fab00-3fd6-5f24-a386-0f6449de242f","inventory_key":"museum-nl:valkhof-museum","name":"Valkhof Museum","city":"Nijmegen","province":"Gelderland","street_address":"Kelfkensbos 59","postal_code":"6511 TB","country":"NL","website_url":"https://valkhofmuseum.nl","latitude":null,"longitude":null,"summary":"Ontdek kunst op het snijvlak van verleden en heden. Valkhof Museum verbindt beeldende kunst met geschiedenis en archeologie, waardoor onverwachte verbanden ontstaan. De tentoonstellingen nodigen je uit om vertrouwde verhalen opnieuw te bekijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude kunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Overzicht_museum_-_Nijmegen_-_20358791_-_RCE.jpg/1280px-Overzicht_museum_-_Nijmegen_-_20358791_-_RCE.jpg","caption":"Valkhof Museum — Overzicht museum - Nijmegen - 20358791 - RCE","credit":"A. J. van der Wal","source_url":"https://commons.wikimedia.org/wiki/File:Overzicht_museum_-_Nijmegen_-_20358791_-_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"7c25dca7-6154-513e-a8c6-3922f645a55c","inventory_key":"art-audit:56","name":"Beeldengalerij Het Depot","city":"Wageningen","province":"Gelderland","street_address":"Arboretumlaan 4","postal_code":"6703 BD","country":"NL","website_url":"https://www.hetdepot.nl/","latitude":null,"longitude":null,"summary":"De menselijke gestalte staat centraal in Het Depot. Torsen en lichaamsfragmenten laten zien hoeveel expressie een beeld kan dragen. Binnen en tussen de bomen ontdek je hedendaagse sculpturen vanuit telkens een ander gezichtspunt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","hedendaagse kunst","beeldentuin"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/Beeldengalerij_Het_Depot.jpg/1280px-Beeldengalerij_Het_Depot.jpg","caption":"Beeldengalerij Het Depot — Beeldengalerij Het Depot","credit":"Hay Kranen","source_url":"https://commons.wikimedia.org/wiki/File:Beeldengalerij_Het_Depot.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"d11204f0-0880-5d01-b334-a3a1cb0eea58","inventory_key":"museum-nl:stedelijk-museum-kampen","name":"Stedelijk Museum Kampen","city":"Kampen","province":"Overijssel","street_address":"Oudestraat 133","postal_code":"8261 CK","country":"NL","website_url":"https://stedelijkmuseumkampen.nl/cms/index.php","latitude":52.558867,"longitude":5.91659,"summary":"Naast de geschiedenis van Kampen biedt dit museum ruimte aan wisselende kunsttentoonstellingen. Ontdek eigentijdse makers in een historisch decor. Bekijk het programma om te zien welke kunstpresentatie er tijdens jouw bezoek te zien is.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Interieur_Stedelijk_Museum_Kampen_DSCF5238.JPG/1280px-Interieur_Stedelijk_Museum_Kampen_DSCF5238.JPG","caption":"Stedelijk Museum Kampen — Interieur Stedelijk Museum Kampen DSCF5238","credit":"G.Lanting","source_url":"https://commons.wikimedia.org/wiki/File:Interieur_Stedelijk_Museum_Kampen_DSCF5238.JPG","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"13d786ee-7180-5e3f-ac5f-3aa0961316ad","inventory_key":"museum-nl:japanmuseum-sieboldhuis","name":"Japanmuseum SieboldHuis","city":"Leiden","province":"Zuid-Holland","street_address":"Rapenburg 19","postal_code":"2311 GE","country":"NL","website_url":"https://www.sieboldhuis.org/","latitude":52.159641,"longitude":4.484616,"summary":"Ontdek Japan door de verzameling van Philipp Franz von Siebold. Prenten, kunstvoorwerpen en gebruiksobjecten staan naast natuurhistorische stukken. Wisselende tentoonstellingen verdiepen de kennismaking met Japanse beeldcultuur en makers.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["Japanse kunst","prentkunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/WLANL_-_Pachango_-_Sieboldhuis.jpg/1280px-WLANL_-_Pachango_-_Sieboldhuis.jpg","caption":"Japanmuseum SieboldHuis — WLANL - Pachango - Sieboldhuis","credit":"Niels from Amsterdam, NL","source_url":"https://commons.wikimedia.org/wiki/File:WLANL_-_Pachango_-_Sieboldhuis.jpg","license":"CC BY-SA 2.0"}],"is_art_museum":true},{"id":"ed17251a-807b-5603-932d-a62ca132c1ca","inventory_key":"art-audit:61","name":"Electric Ladyland","city":"Amsterdam","province":"Noord-Holland","street_address":"Tweede Leliedwarsstraat 5","postal_code":"1015 TB","country":"NL","website_url":"https://electric-lady-land.com/","latitude":null,"longitude":null,"summary":"Stap een wereld binnen waarin kleuren oplichten. Electric Ladyland verkent fluorescentie via kunst, mineralen en alledaagse materialen. De ruimtelijke lichtomgeving maakt van kijken een ervaring waarin je zelf deel van het beeld wordt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["lichtkunst","immersieve kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Electric_Ladyland_museum_entrance_2016.jpg/1280px-Electric_Ladyland_museum_entrance_2016.jpg","caption":"Electric Ladyland — Electric Ladyland museum entrance 2016","credit":"Robin Sheat -- Eythian","source_url":"https://commons.wikimedia.org/wiki/File:Electric_Ladyland_museum_entrance_2016.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"ecf42871-4733-5818-8ffe-ad8469b6bfa7","inventory_key":"museum-nl:museum-bredius","name":"Museum Bredius","city":"Den Haag","province":"Zuid-Holland","street_address":"Lange Vijverberg 14","postal_code":"2513 AC","country":"NL","website_url":"https://museumbredius.nl/","latitude":52.081245,"longitude":4.312499,"summary":"Ontmoet de verzamelaarsblik van Abraham Bredius. Hollandse schilderijen en tekeningen vormen het hart van dit intieme museum, met daarnaast zilver, porselein en meubels. Een fijne plek om rustig te kijken naar kleine en grote details.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude meesters","schilderkunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Bredius_Museum.jpg/1280px-Bredius_Museum.jpg","caption":"Museum Bredius — Bredius Museum","credit":"Pvt pauline","source_url":"https://commons.wikimedia.org/wiki/File:Bredius_Museum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"a9585bd2-a2bd-5126-9858-93ab6c183163","inventory_key":"museum-nl:zeeuws-museum","name":"Zeeuws Museum","city":"Middelburg","province":"Zeeland","street_address":"Abdij 3","postal_code":"4331 BK","country":"NL","website_url":"https://www.zeeuwsmuseum.nl/nl","latitude":51.500133,"longitude":3.613399,"summary":"Laat je verrassen door Zeeuwse kunst en vormgeving. Monumentale wandtapijten, streekdracht en hedendaagse ontwerpen verbinden verschillende eeuwen. De wonderkamers maken zichtbaar hoe verzamelen telkens nieuwe verbanden legt tussen kunst, voorwerpen en verhalen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["textielkunst","mode","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Middelburg%2C_Zeeuws_Museum.jpg/1280px-Middelburg%2C_Zeeuws_Museum.jpg","caption":"Zeeuws Museum — Middelburg, Zeeuws Museum","credit":"Norbert Schnitzler","source_url":"https://commons.wikimedia.org/wiki/File:Middelburg,_Zeeuws_Museum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"63dcb672-0d3c-5949-828c-4b215302b67c","inventory_key":"art-audit:67","name":"Maelwael Van Lymborch Huis","city":"Nijmegen","province":"Gelderland","street_address":"Burchtstraat 63","postal_code":"6511 RC","country":"NL","website_url":"https://maelwaelvanlymborch.nl/","latitude":null,"longitude":null,"summary":"Ontdek de rijk gekleurde wereld van de gebroeders Van Lymborch en Johan Maelwael. Presentaties over hun miniaturen brengen de vroege schilderkunst dichtbij. De historische kelder verbindt hun verhaal met het Nijmegen waarin zij werkten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["miniatuurkunst","middeleeuwse kunst","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Maelwael_Van_Lymborch_Huis_Nijmegen_05.jpg/1280px-Maelwael_Van_Lymborch_Huis_Nijmegen_05.jpg","caption":"Maelwael Van Lymborch Huis — Maelwael Van Lymborch Huis Nijmegen 05","credit":"FrDr","source_url":"https://commons.wikimedia.org/wiki/File:Maelwael_Van_Lymborch_Huis_Nijmegen_05.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"ec434d6d-013a-5b24-8781-f692f9282f6b","inventory_key":"art-audit:69","name":"Museum de Fundatie – Kasteel het Nijenhuis","city":"Heino","province":"Overijssel","street_address":"''t Nijenhuis 10","postal_code":"8131 RD","country":"NL","website_url":"https://www.museumdefundatie.nl/","latitude":null,"longitude":null,"summary":"Kunst ontmoet het landschap rond Kasteel het Nijenhuis. De verzameling van Museum de Fundatie omvat schilderijen, sculpturen en toegepaste kunst. Binnen en in de beeldentuin kun je werken vanuit verschillende tijden naast elkaar ontdekken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","